"""Render diagnostic deliverables from saved analysis results, no source outcomes."""
from __future__ import annotations
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "outputs/mlb-v18-empirical-diagnosis-v1"


def md_table(headers, rows):
    def cell(x):
        return str(x).replace("|", "\\|")
    return "\n".join(["| "+" | ".join(cell(x) for x in headers)+" |", "|"+"|".join(["---"]*len(headers))+"|", *["| "+" | ".join(cell(x) for x in row)+" |" for row in rows]])


def main():
    s = json.loads((OUT/"pa/summary.json").read_text(encoding="utf-8"))
    ws = json.loads((OUT/"whole-game/summary.json").read_text(encoding="utf-8"))
    wm = json.loads((OUT/"whole-game/metrics-by-version.json").read_text(encoding="utf-8"))
    daily = next(x for x in wm if x["lineage"].startswith("mlb-v18-daily-slate:"))
    r = pd.read_csv(OUT/"pa/regimes.csv").set_index("regime")
    c = pd.read_csv(OUT/"pa/class-calibration.csv")
    bands = pd.read_csv(OUT/"pa/probability-bands.csv")
    leads = pd.read_csv(OUT/"pa/calibration-leads.csv")
    doubles = leads[leads.band.str.startswith("DOUBLE")].set_index("window")
    a, f5 = s["windows"]["all"], s["windows"]["fold5"]
    db, db5 = doubles.loc["all"], doubles.loc["fold5"]
    boot = json.loads((OUT/"pa/calibration-lead-bootstrap.json").read_text(encoding="utf-8"))["DOUBLE [0.05,0.1)"]
    cold = r.loc["either_prior_missing"]
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    fold_rows=doubles.loc[[f"fold{k}" for k in range(1,6)]]
    fig,axes=plt.subplots(1,2,figsize=(12,4.8),constrained_layout=True)
    x=list(range(1,6))
    for col,color,label in [("v18_predicted","#b2182b","V18 predicted"),("v14_predicted","#7b6393","V14 on same PAs"),("observed","#2166ac","Observed doubles")]:
        axes[0].plot(x,100*fold_rows[col],"o-",color=color,label=label)
    axes[0].set(xticks=x,xlabel="Fitted fold",ylabel="Double frequency (%)",title="PAs with V18 P(double) from 5% to 10%")
    axes[0].legend(frameon=False,fontsize=9)
    point=100*fold_rows.v18_bias.to_numpy()
    axes[1].errorbar(x,point,yerr=[point-100*fold_rows.v18_bias_ci_lower.to_numpy(),100*fold_rows.v18_bias_ci_upper.to_numpy()-point],fmt="o",color="#b2182b",capsize=4)
    axes[1].axhline(0,color="#888",linestyle="--",linewidth=1)
    axes[1].set(xticks=x,xlabel="Fitted fold",ylabel="Predicted minus observed (percentage points)",title="Same direction in all five folds")
    for ax in axes:
        ax.spines[["top","right"]].set_visible(False)
    fig.suptitle("Recurring doubles overprediction in stored PA evidence\nHistorical timing uncertain; intervals are nominal game-cluster 95%",fontsize=13)
    fig.savefig(OUT/"pa/doubles-band-by-fold.png",dpi=150,facecolor="white")
    plt.close(fig)
    text = ["# What V18 misses: saved-evidence diagnosis", "", "Prepared for James. Analysis snapshot: "+s["generatedAtUtc"]+". Branch `codex/mlb-starter-duration-source-intake-v1`, committed HEAD `9ca94e9c0135cde7d2b852560d59a43fa45a5c17`. Independent publication/monitoring locators are outside this frozen diagnostic cohort.", "",
    f"**The most repeatable stored PA error is excessive double probability in the 5–10% prediction band.** Across {int(db.pa_count):,} PAs in {int(db.games):,} registered game IDs, V18 predicted {db.v18_predicted:.2%} doubles and observed {db.observed:.2%}: **+{100*db.v18_bias:.3f} percentage points**, or about {1000*db.v18_bias:.2f} excess expected doubles per 1,000 PAs. The direction repeats in all five fitted folds. Today's fold-5 estimator also shows it: {db5.v18_predicted:.2%} predicted versus {db5.observed:.2%} observed on {int(db5.pa_count):,} PAs/{int(db5.games):,} games. This is a recurring calibration weakness in stored historical evidence; **historical timing remains uncertified, so prospective recurrence and a useful correction are unproven.**", "",
    f"**The available whole-game slate leans too far toward the home team, but only on one date.** The 13 September 8 forecasts overpredicted home margin by {daily['marginals']['homeMinusAwayRuns']['bias']:.2f} runs on average; 10/13 errors were positive and 2/13 exceeded five runs in absolute size. These forecasts have pregame capture evidence but no verified completion timestamp. **None of the 17 current-pipeline forecasts with verified pregame creation clocks has a matching final in the available export.** No recurring operational whole-game weakness or strength is established.", "",
    "**BIP_OUT and cold-start concerns do not support a stable priority.** BIP_OUT aggregate bias reverses in later folds. The either-player prior-missing loss difference versus V14 reverses in fold 4; no predefined context group's paired loss difference survives Holm adjustment. No ensemble, correction function, specialist, calibration or policy was selected.", "",
    "[Sortable regimes and probability bands](regime-table.html) · [Matchup casebook](CASEBOOK.md) · [Exact lineage](lineage/PA_LINEAGE.md) · [Declared protocol](PROTOCOL.md) · [Missing AISP evidence](AISP_EVIDENCE_REQUIREMENTS.md)", "",
    "**Population and timing.** The primary PA population is 501,539 saved Development OOF predictions, March 20, 2024–August 13, 2026, with 6,664 registered game IDs, 507 dates, 77 ISO weeks, 874 batters, 1,273 pitchers and 2,021 distinct players. Team metadata identifies all 30 teams on the 494,432-row context subset; 7,107 PAs/94 game IDs lack that team/context join. Two registered game IDs contain only one archived PA each, so game counts describe saved identity coverage rather than certified complete-game coverage. Every PA remains in the primary metrics. No prices, decisions, NO_BET or positions determined eligibility.", "",
    "Only fold 5 uses today's frozen `MLB_V18_HGB_PA` estimator (`44ec4f457741f1aaeff42b81af1be5fd2712e494709ff1a0a8f0742b88d71c8b`), with training through May 1, 2026. It contributes 101,264 PAs/1,342 games. Other rows belong to four different fitted V18 versions. These are PA-horizon predictions conditional on recorded pre-PA state, not pregame game forecasts. Exact estimator, preprocessor, raw/treated/encoded order, target crosswalk and cutoffs are retained in [pa-lineage.json](lineage/pa-lineage.json). The eight outcomes retain their original definitions; Brier sums across eight classes, while winner Brier is the separate binary score.", "",
    "The saved matching V14 HGB is aligned on PA ID, game ID, fold and observed target; its 51 additional held rows are excluded. It is a descriptive reference with its own treatment/fitted identity and historical timing limitations. RF OOF was inventoried but not used as a comparator or model. The ordinary forecast inventory contains 32 objects/31 unique games: 13 September 8 daily forecasts, 17 current-pipeline forecasts and two preserved prototype versions of one September 7 game. Fourteen unique games have saved final-state evidence, with the prototype reported separately and no duplicated game pooled.", "",
    "All five historical preprocessing/fitted folds remain potentially affected by availability or completion ordering. Fold-2 training contains at least 55 proven future labels; its conservative whole-game exclusion covers 70 PAs. Existing completion/rolling flags also identify unresolved 2026 availability. Removing evaluation rows cannot repair those fitted objects, annual/rolling priors or downstream transition authority. The existing conservative key sensitivity is not a clean cohort: it leaves 291,202 scored PAs/3,876 games and no certified fold-5 confirmation. Certified historical metric eligibility remains zero. No chronology reconstruction was attempted. The 13,837 remaining Final OOT observations stay sealed; all three permanent whole-game exclusions were checked on identities before outcomes. This is not a Final OOT evaluation.", "",
    "**Measured PA results.** Positive loss difference means V18 worse than V14; log loss uses natural logarithms.", ""]
    text.append(md_table(["Window / fitted version","PAs","Games","Dates / weeks","V18 log loss","V18 − V14","V18 summed Brier"], [[name, f"{v['pa_count']:,}",f"{v['games']:,}",f"{v['dates']} / {v['weeks']}",f"{v['v18_log_loss']:.6f}",f"{v['delta_log_loss']:+.6f}",f"{v['v18_brier']:.6f}"] for name,v in s["windows"].items() if name in ["all","fold1","fold2","fold3","fold4","fold5"]]))
    text += ["", f"Overall difference {a['delta_log_loss']:+.8f}; nominal game-cluster 95% interval [{a['delta_log_loss_game_cluster_ci95'][0]:+.6f}, {a['delta_log_loss_game_cluster_ci95'][1]:+.6f}]. The fixed 28-day block bootstrap also includes zero. This provides no general V18 advantage over V14. PA loss is asymmetric: median {s['lossQuantiles']['0.5']:.3f}, 90th percentile {s['lossQuantiles']['0.9']:.3f}, 99th {s['lossQuantiles']['0.99']:.3f}, maximum {s['lossQuantiles']['1']:.3f}. {s['paLossAtLeast3']:,} PAs ({s['paLossAtLeast3']/a['pa_count']:.2%}) have loss ≥3; {s['paLossAtLeast5']:,} ({s['paLossAtLeast5']/a['pa_count']:.2%}) have loss ≥5. Rare realized outcomes naturally produce large surprisal; these thresholds are not automatic model failures.", ""]
    allc=c[c.window=="all"].set_index("class")
    fc=c[c.window=="fold5"].set_index("class")
    text.append(md_table(["Outcome","Predicted frequency","Observed frequency","Bias, pp","Fold-5 bias, pp"],[[name,f"{v.predicted:.3%}",f"{v.observed:.3%}",f"{100*v.bias:+.3f}",f"{100*fc.loc[name,'bias']:+.3f}"] for name,v in allc.iterrows()]))
    text += ["", "The small aggregate biases conceal stronger probability-band errors. All 383 nonempty fixed band/window tests and their Holm-adjusted values are retained in [probability-bands.csv](pa/probability-bands.csv); the report does not infer improvement from post-scan nominal intervals.", "",
    "**Doubles: recurring stored calibration weakness, timing uncertain.** The 5–10% band contains 4,426 observed doubles, 507 dates, 77 weeks, 812 batters, 1,244 pitchers and 1,941 distinct players, with all 30 teams represented where team identity is available. It covers "+f"{db.pa_count/a['pa_count']:.2%}"+" of the full PA archive. The class probability itself is observable at PA forecast time; it does not define a pregame lineup condition.", ""]
    text.append(md_table(["Fold","PAs / games","V18 predicted","V14 predicted on same PAs","Observed","V18 bias, pp"],[[str(k),f"{int(doubles.loc['fold'+str(k),'pa_count']):,} / {int(doubles.loc['fold'+str(k),'games']):,}",f"{doubles.loc['fold'+str(k),'v18_predicted']:.2%}",f"{doubles.loc['fold'+str(k),'v14_predicted']:.2%}",f"{doubles.loc['fold'+str(k),'observed']:.2%}",f"{100*doubles.loc['fold'+str(k),'v18_bias']:+.3f}"] for k in range(1,6)]))
    text += ["", f"Each individual fold's double-band bias survives adjustment across the 383 band/window tests. The pooled nominal game-cluster interval is [{100*db.v18_bias_ci_lower:.3f}, {100*db.v18_bias_ci_upper:.3f}] pp; the 23-block temporal bootstrap is [{100*boot['four_week']['lower'][1]:.3f}, {100*boot['four_week']['upper'][1]:.3f}] pp. Dropping the most represented batter, pitcher, date or known team leaves +0.931 to +0.970 pp; the existing conservative timing-key sensitivity leaves +0.933 pp. The fitted estimator still has timing uncertainty after that filter.", "",
    f"V14 also overpredicts doubles in these V18-defined bands: pooled {db.v14_predicted:.2%} versus {db.observed:.2%}, a +{100*db.v14_bias:.3f} pp bias. V18's double-class Brier is {db.class_brier_difference:+.6f} worse, with a nominal post-scan interval [{db.class_brier_difference_ci_lower:+.6f}, {db.class_brier_difference_ci_upper:+.6f}]. Its full eight-class PA loss difference on these rows is only {db.delta_pa_log_loss:+.6f}, with game-cluster interval [{db.delta_pa_log_loss_ci_lower:+.6f}, {db.delta_pa_log_loss_ci_upper:+.6f}]; the block interval differs and is positive. This metric/dependence sensitivity prevents a claim that correcting this one class will improve the whole model. Bands are defined by V18, not an independent common risk score, so the V14 contrast is conditional and does not establish causal superiority.", "",
    "**Other patterns remain leads or reversals.** Singles in the 20–30% band average 21.90% predicted versus 18.57% observed (10,676 PAs/3,564 games); V14 predicts 20.60% on the same rows. Home runs in the 5–10% band average 5.99% versus 4.97% (35,728 PAs/5,612 games); V14 predicts 5.58%. Their scalar class Brier and calibration details are retained in [calibration-leads.csv](pa/calibration-leads.csv), with temporal rows, support and sensitivity. These follow-ups were selected after the fixed-band scan and are not independent confirmation or selected corrections.", "",
    "BIP_OUT aggregate bias is −1.306, −0.166, −0.160, +0.132 and +0.065 pp across folds 1–5. Its negative pooled bias is driven by earlier windows; a stable global underprediction claim does not survive the later checks. The earlier report's four contextual BIP_OUT leads also reversed or weakened. The current 30–40% band underpredicts BIP_OUT by 1.129 pp overall, but that pooled result does not restore a stable contextual specialist priority.", "",
    f"Either-player prior-missing support is {int(cold.pa_count):,} PAs/{int(cold.games):,} games/{int(cold.weeks)} weeks. V18's loss difference is {cold.delta_log_loss:+.6f} (nominal game-cluster interval [{cold.delta_ci_lower:+.6f}, {cold.delta_ci_upper:+.6f}]), but Holm-adjusted p={cold.delta_p_holm:.3f}. Early/fold-4/fold-5 differences are {cold.early_folds1_3_delta_log_loss:+.6f}, {cold.fold4_delta_log_loss:+.6f}, {cold.fold5_delta_log_loss:+.6f}. Removing dominant entities retains a small positive pooled difference, which does not remove the temporal reversal or selection uncertainty. Pitcher-prior-missing is consistently positive in those summaries (+0.000689/+0.000289/+0.001448) but its game interval includes zero and adjusted p=1. Flags mean missing source history, not automatically a rookie, debut or role change.", "",
    "Across 66 nonempty predefined context regimes, **zero paired-loss tests survive Holm adjustment**. Nineteen declared groups are empty or constant-state contrasts without data. Temperature and bullpen-availability flags do not support a present-versus-missing comparison. Actual starter/reliever role, times through order, lineup certainty, actual workload, park and weather are unavailable in historical PA context. Prior starter share is only prior role tendency; fastball usage is pitch mix, not workload; inning/outs/bases are pre-PA realized conditions, not pregame information.", "",
    "**Strengths and uncertainty.** Predicted uncertainty carries useful ordering descriptively: <40% maximum-probability PAs have 38.08% top-class accuracy and 1.522 loss; the ≥60% group has 59.09% accuracy and 1.266 loss. But that high-confidence group predicts 62.24% success, has only 4,199 PAs, and lacks sufficient later per-phase support for a recurring strength claim. The dominant 40–50% band is close on average (45.02% predicted versus 45.29% accuracy). Lower subgroup loss also reflects different outcome difficulty; observed outcome-mix entropy and saved reference scores accompany every row. No distinct recurring V18 advantage was established.", "",
    "**Whole-game errors and distributions.** September 8 support is 13 games, 26 teams, 234 saved lineup players, one date and one ISO week. This lineage uses fold-5 V18 plus accepted transition fold 4. Selection is earliest valid pregame creation where present; capture-only forecasts are a separate exploratory cohort. Original variants are preserved. Stored final game-state observations, independently matched to event/MLBAM/source/revision/clocks, supply outcomes; the export's official-outcomes table is empty.", ""]
    text.append(md_table(["Quantity","Mean predicted − actual","MAE","5th / median / 95th signed error","|error| ≥5","CRPS","90% coverage"],[[name,f"{v['bias']:+.3f}",f"{v['mae']:.3f}"," / ".join(f"{v['signed_error_quantiles'][k]:+.2f}" for k in ["q05","q50","q95"]),f"{v['absolute_errors_ge_5']}/13",f"{v['crps']:.3f}","13/13"] for name,v in daily["marginals"].items()]))
    text += ["", f"Home-win log loss is {daily['winner_log_loss']:.4f}, binary Brier {daily['winner_brier']:.4f}; mean P(home) is {daily['mean_home_probability']:.2%}, versus {daily['observed_home_win_rate']:.2%} home wins. A compatible reference forecast at the same horizon is not available. The home-margin mean remains +1.46 to +2.03 after dropping any one game/team pairing, but the within-slate game-bootstrap interval [+0.66,+3.18] cannot substitute for temporal replication. One date supplies no dominant-date sensitivity or temporal-block inference.", "",
    "The saved total-score SD ranges from 3.97 to 4.49 runs; mean 90% total interval width is 13.46 runs. All 13 totals lie within those intervals. This does not establish appropriate uncertainty scaling, overdispersion or calibrated 90% coverage: sample size and temporal support are inadequate. Exact saved marginal PMFs support CRPS and empirical intervals; no joint ordinary score population is available for energy scoring. It was not regenerated. The separate September 7 TOR–ATH prototype underpredicts total by 3.11 runs and home margin by 1.95; its two identical numerical variants remain separate and do not create two observations.", "",
    "**Most informative cases.** TB–ATL misses home margin by +6.20 runs despite only +0.61 total error, so a simple total-run shift would not explain that miss. STL–SF total error is +5.66; CLE–BAL is −5.03, showing both tail directions. COL–NYY (margin −0.48) and CHC–MIL (+0.21) are successful cases with the same projected-lineup limitation. Their presence prevents attributing all failures to that shared input state. CIN–LAD supplies the declared median-error example. The casebook separates model-input, PA calibration and simulator hypotheses; aggregate finals do not identify a cause.", "",
    "In PA evidence, two one-PA archive fragments rank as extreme game-frequency cases; they are coverage warnings rather than severe complete-game forecast errors. Among rows with substantial PA coverage, MIL–NYY on March 29, 2025 and COL–AZ on May 17, 2025 have high PA loss under both V18 and V14. The eight largest individual PA surprisals are triples from fold 1, not today's estimator, and most have established rolling histories. See [CASEBOOK.md](CASEBOOK.md) for case definitions, controls, identities and recorded context.", "",
    "**Inference and limits.** The original protocol precedes outcome access. Folds 1–3 form the early summary; folds 4 and 5 are later temporal checks. All were used by previous research, so none is an independently untouched confirmation set. Intervals use game-cluster score uncertainty plus deterministic 2,000-replicate game and fixed nonoverlapping 28-day-block bootstrap, stratified by season. Fold 5 has only five populated blocks; its temporal intervals remain descriptive. Holm families cover 66 context-loss tests, 528 context-class-bias tests, 64 aggregate class/window tests and 383 probability-band/window tests. The selected-band sensitivity follow-up does not create new independent confirmation. Overlapping groups are not additive contributions to total error.", "",
    "**Next investigations, after this evidence.** First, join Claude's eligible immutable final export to the 17 creation-qualified forecasts and repeat the already frozen horizon/selection rules across new dates; this directly tests the +1.82-run home-margin lead. Second, prospectively check the already declared 5–10% double-probability band, preserving all eight probabilities and the reference where compatible; this tests the most persistent measured PA calibration error without choosing a correction. Third, inspect original input and saved-path provenance for severe margin-versus-total cases, separating confirmed/projected lineups and actual final-linked starter usage when supplied. These are questions for future bounded work, not authorization to retrain, recalibrate, simulate or deploy.", "",
    "**Reproduction and checks.** From the repository, run `.\\.venv\\Scripts\\python.exe scripts/run_mlb_v18_empirical_diagnosis_v1.py`. It reads the pinned local artifacts and rebuilds diagnostics only. PA scores exactly match the existing scorers and reproduce the saved recovery means within 2.3×10⁻¹⁶. All 60 marginal CRPS calculations reconcile within 1.12×10⁻¹⁵; saved PMFs/means, 32 snapshot/forecast identity/hash bindings, 196 export aliases and 17 creation-clock chains pass. Eight negative identity/clock guards reject invalid evidence. Source/artifact/script hashes and physical-read receipts are listed in [artifact-manifest.json](artifact-manifest.json). Plot layouts were inspected; the HTML table passed source-hash, link and JavaScript checks, with no browser available for visual interaction testing.", "",
    f"No model fitting, inference, forecast simulation, source acquisition, AISP/database modification, policy action or operating-task changes occurred. The reused paired receipt reports {ws['paired_completed_games']} scored games as of {ws['paired_scoring_as_of']}; this diagnosis did not run its scorer. Existing pair/NFL restoration ownership and the September 12 20:52:51.349 UTC latest-restoration deadline remain in force. Subsequent live locators can advance independently of this report.", ""]
    text += ["**Empirical plots.** [Doubles band and uncertainty](pa/doubles-band-by-fold.png) · [Eight-class calibration](pa/pa-calibration.png) · [Class bias by fold](pa/pa-class-bias-by-fold.png) · [PA loss and confidence](pa/pa-error-and-confidence.png) · [Whole-game signed-error distributions](whole-game/empirical-error-ecdf.png) · [Winner calibration and saved spread](whole-game/winner-calibration-and-spread.png)", ""]
    (OUT/"REPORT.md").write_text("\n".join(text),encoding="utf-8")
    case = ["# Matchup and PA casebook", "", "Whole-game errors and PA conditional errors are different units. No postgame explanation in this casebook becomes a pregame selection rule.", "", (OUT/"whole-game/casebook.md").read_text(encoding="utf-8"), "", "## PA game summaries", "", "The declared top-three metrics retain two one-PA Cleveland doubleheader fragments. Those rows do not support complete-game conclusions or matched full-game control comparisons. They are preserved in the CSV as coverage warnings. The supplementary substantial-coverage cases are explicitly labeled post-scan additions; their purpose is readable explanation, not independent inference.", ""]
    cases=pd.read_csv(OUT/"pa/pa-game-casebook.csv")
    case.append(md_table(["Selection","Date","Away–home","Fold","Archived PAs","V18 PA loss","V14 PA loss","Predicted / observed BIP_OUT"],[[v.selection,v.game_date,f"{v.awayTeamAbbrev}–{v.homeTeamAbbrev}",int(v.foldNumber),int(v.pa_count),f"{v.pa_log_loss:.4f}",f"{v.v14_pa_log_loss:.4f}",f"{v.bip_predicted:.1%} / {v.bip_observed:.1%}"] for _,v in cases.iterrows()]))
    case += ["", "Controls in that table match fold first, then available archived PA count and predicted entropy; their median/lower-quartile loss selection uses outcomes for explanation. They are not causal controls, and a full-game control cannot be closely count-matched to a one-PA fragment. Recorded exposure, platoon, state and rest shares, game IDs and original selection labels are in [pa-game-casebook.csv](pa/pa-game-casebook.csv). Actual runs/winner probabilities are unavailable for these PA-only historical rows and are not inferred from them.", ""]
    if (OUT/"pa/case-notes.md").exists():
        case += [(OUT/"pa/case-notes.md").read_text(encoding="utf-8"), ""]
    else:
        case += ["Detailed per-class case enrichment is provided separately in `pa/case-details.json` when the full reproduction command completes.", ""]
    case += ["Exact forecast and final references for whole-game cases: [casebook.json](whole-game/casebook.json). Exact PA model/preprocessor identity by fold: [pa-lineage.json](lineage/pa-lineage.json). All original severe PA rows and initial controls: [severe-pa-cases.csv](pa/severe-pa-cases.csv). The initial control is shared across several cases and must not be counted as separate observed PAs; refined distinct controls are labeled in the enrichment.", ""]
    (OUT/"CASEBOOK.md").write_text("\n".join(case),encoding="utf-8")
    inventory=pd.read_csv(OUT/"whole-game/forecast-inventory.csv")
    inventory[inventory.created_at.notna()].to_csv(OUT/"missing-current-forecast-finals.csv",index=False)
    print("Wrote REPORT.md, CASEBOOK.md and missing-current-forecast-finals.csv")


if __name__ == "__main__":
    main()
